body:
$n = '{{newname}}'
if ($n -notmatch '^[A-Za-z0-9-]{1,15}$' -or $n -match '^-|-$|^[0-9]+$') { Write-Output 'Not changed: use 1 to 15 letters, numbers or hyphens, not only digits and no hyphen at the start or end.'; exit 1 }
Write-Output "Current name: $env:COMPUTERNAME"
if ($env:COMPUTERNAME -ieq $n) { Write-Output 'Already has that name.'; exit 0 }
if ((Get-CimInstance Win32_ComputerSystem).PartOfDomain) { Write-Output 'Not changed: this computer is joined to a domain. Rename it from Active Directory (or with domain credentials).'; exit 1 }
try { Rename-Computer -NewName $n -Force -ErrorAction Stop; Write-Output "Renamed to $n. Restart the computer to finish." } catch { Write-Output ('Failed: ' + $_.Exception.Message); exit 1 }
